// --- commerce: catalogue, orders ----------------------------------------------------------------

/** `orders.OrderStatus`; labels `orders::enums.order_status.<code>`, tones from the manifest. */
export const OrderStatus = Enum.of({
  PendingPayment: ["pending_payment", { tone: Tone.Warning }],
  Paid: ["paid", { tone: Tone.Success }],
  Cancelled: ["cancelled", { tone: Tone.Default }],
  Expired: ["expired", { tone: Tone.Default }],
});

/** One of the codes above. */
export type OrderStatus = Enum.Value<typeof OrderStatus>;

/** `orders.OrderStatus`, codes in source order. */
export const OrderStatus$ = z.enum(["pending_payment", "paid", "cancelled", "expired"]);

/** `orders.OrderAdjustment`: `label` is an i18n key of the module that added it. */
export const OrderAdjustment$ = z.object({
  code: z.string(),
  label: z.string(),
  amountMinor: z.number().int(),
});

/** `orders.OrderTotals`. */
export const OrderTotals$ = z.object({
  currency: currencyCode(),
  subtotalMinor: z.number().int().min(0),
  adjustments: z.array(OrderAdjustment$),
  totalMinor: z.number().int().min(0),
});

/** `orders.RequestedLine`. */
export const RequestedLine$ = z.object({
  variantId: publicId("var"),
  quantity: z.number().int().min(1),
});

/** `orders.RequestedLine` as a class, so the create-order form extends the action's own line. */
export class RequestedLine extends remoteShape("orders.RequestedLine", RequestedLine$) {}

/** `orders.PricedLine`. */
export const PricedLine$ = RequestedLine$.extend({ unitPriceMinor: z.number().int() });

/** `orders.OrderView`, served at the pinned version (2027-03-01). */
export const OrderView$ = z.object({
  id: publicId("ord"),
  status: OrderStatus$,
  totals: OrderTotals$,
  lines: z.array(PricedLine$),
  createdAt: isoDateTime(),
});

/** `orders.OrdersTodayOutput`. */
export const OrdersTodayOutput$ = z.object({
  count: z.number().int(),
  revenueMinor: z.number().int(),
  currency: currencyCode(),
  hourly: z.array(z.number().int()).length(24),
});

/** `catalogue.VariantHit`. */
export const VariantHit$ = z.object({
  variantId: publicId("var"),
  productId: publicId("prd"),
  sku: z.string(),
  title: z.string(),
  trackInventory: z.boolean(),
});

/** `orders.OrderPaid`: the `orders.order.paid.v1` payload. */
export const OrderPaid$ = z.object({
  orderId: publicId("ord"),
  customerId: publicId("usr"),
  paymentId: z.string(),
  totalMinor: z.number().int().min(0),
  currency: currencyCode(),
});

/** Everything this build uses from `@acme/service-commerce`. */
export const Commerce = {
  modules: {
    Catalogue: moduleRef("commerce", "catalogue"),
    Orders: moduleRef("commerce", "orders"),
  },
  actions: {
    CreateOrder: actionRef("orders.order.create@1", {
      input: z.object({
        lines: z.array(RequestedLine$).min(1).max(100),
        extensions: z
          .object({
            loyalty: z
              .object({ redeemPoints: z.number().int().min(1).max(1_000_000) })
              .exactOptional(),
          })
          .default({}),
      }),
      output: z.object({
        orderId: publicId("ord"),
        status: OrderStatus$,
        totals: OrderTotals$,
        paymentClientSecret: z.string(),
      }),
      http: { method: HttpMethod.Post, path: "/orders" },
      risk: Risk.L1,
    }),
    CancelOrder: actionRef("orders.order.cancel@1", {
      input: z.object({ orderId: publicId("ord") }),
      output: z.object({ orderId: publicId("ord"), status: OrderStatus$ }),
      http: { method: HttpMethod.Put, path: "/orders/:orderId/cancel" },
      risk: Risk.L2,
      ux: {
        confirm: I18n.orders.actions.order.cancel.confirm,
        success: I18n.orders.actions.order.cancel.success,
      },
    }),
  },
  queries: {
    GetOrder: queryRef("orders.order.get@1", {
      input: z.object({ orderId: publicId("ord") }),
      output: OrderView$,
      http: { method: HttpMethod.Get, path: "/orders/:orderId" },
    }),
    ListOrders: queryRef("orders.order.list@1", {
      input: z.object({
        cursor: z.string().exactOptional(),
        limit: z.number().int().min(1).max(100).default(20),
        status: OrderStatus$.exactOptional(),
      }),
      output: z.object({
        items: z.array(OrderView$),
        nextCursor: z.string().exactOptional(),
        hasMore: z.boolean(),
      }),
      http: { method: HttpMethod.Get, path: "/orders" },
    }),
    OrdersToday: queryRef("orders.order.stats_today@1", {
      input: z.object({}),
      output: OrdersTodayOutput$,
      http: { method: HttpMethod.Get, path: "/orders/stats/today" },
    }),
    GetVariantByBarcode: queryRef("catalogue.variant.get_by_barcode@1", {
      input: z.object({ barcode: z.string().regex(/^\d{8,14}$/) }),
      output: VariantHit$,
      http: { method: HttpMethod.Get, path: "/variants/by-barcode/:barcode" },
    }),
  },
  permissions: {
    Order: {
      create: permissionRef("orders.order.create"),
      read: permissionRef("orders.order.read"),
      cancel: permissionRef("orders.order.cancel"),
    },
    Product: { read: permissionRef("catalogue.product.read") },
  },
  widgets: { RevenueToday: widgetRef("orders.revenue_today") },
  events: { OrderPaid: eventRef("orders.order.paid.v1", { payload: OrderPaid$ }) },
  refusals: {
    variant_unavailable: refusalRef("catalogue.variant_unavailable", {
      message: I18n.catalogue.errors.variant_unavailable.message,
    }),
    variant_not_found: refusalRef("catalogue.variant_not_found", {
      message: I18n.catalogue.errors.variant_not_found.message,
    }),
    insufficient_stock: refusalRef("inventory.insufficient_stock", {
      message: I18n.inventory.errors.insufficient_stock.message,
    }),
  },
  enums: { OrderStatus },
} as const;

// --- notifications: messages --------------------------------------------------------------------

/** `messages.NotificationKind`; labels `messages::enums.notification_kind.<code>`. */
export const NotificationKind = Enum.of({
  /** A customer's order was paid; data carries the order id, total and line count. */
  OrderPaid: "order_paid",
});

/** One of the codes above. */
export type NotificationKind = Enum.Value<typeof NotificationKind>;

/** `messages.NotificationKind`, codes in source order. */
export const NotificationKind$ = z.enum(["order_paid"]);

/** `messages.NotificationView`: one inbox entry; the app renders the kind's label with `data`. */
export const NotificationView$ = z.object({
  id: publicId("ntf"),
  kind: NotificationKind$,
  data: z.record(z.string(), z.union([z.string(), z.number()])),
  createdAt: isoDateTime(),
  readAt: isoDateTime().nullable(),
});

/** Everything this build uses from `@acme/service-notifications`. */
export const Notifications = {
  modules: { Messages: moduleRef("notifications", "messages") },
  actions: {
    MarkNotificationRead: actionRef("messages.notification.mark_read@1", {
      input: z.object({ notificationId: publicId("ntf") }),
      output: NotificationView$,
      http: { method: HttpMethod.Put, path: "/notifications/:notificationId/read" },
      risk: Risk.L0,
    }),
  },
  queries: {
    /** `unread` counts the actor's whole inbox, not the page. */
    ListNotifications: queryRef("messages.notification.list@1", {
      input: z.object({
        cursor: z.string().exactOptional(),
        limit: z.number().int().min(1).max(100).default(20),
        unreadOnly: z.boolean().default(false),
      }),
      output: z.object({
        items: z.array(NotificationView$),
        nextCursor: z.string().exactOptional(),
        hasMore: z.boolean(),
        unread: z.number().int().min(0),
      }),
      http: { method: HttpMethod.Get, path: "/notifications" },
    }),
  },
  permissions: {
    Notification: {
      read: permissionRef("messages.notification.read"),
      update: permissionRef("messages.notification.update"),
    },
  },
  events: {
    /**
     * Broadcast as a data-free refresh to the tenant's sessions that hold
     * `messages.notification.read`; the inbox refetches its own entries.
     */
    NotificationCreated: eventRef("messages.notification.created.v1", {
      payload: z.object({
        notificationId: publicId("ntf"),
        principalId: publicId("usr"),
        kind: NotificationKind$,
      }),
      channel: "tenant.{tenantId}.messages",
    }),
  },
  refusals: {
    notification_not_found: refusalRef("messages.notification_not_found", {
      message: I18n.messages.errors.notification_not_found.message,
    }),
  },
  enums: { NotificationKind },
} as const;

